const COMMAND = 'open';

export const PROJECT_RUNTIME_FLAG_SPEC = {
  'rivet-port': { takesValue: true },
  'user-port': { takesValue: true },
  framework: { takesValue: true },
  entry: { takesValue: true },
  'style-framework': { takesValue: true },
  'tailwind-config': { takesValue: true },
  debug: { takesValue: false },
  agent: { takesValue: true },
  'no-git': { takesValue: false },
};

const DEFAULT_SERVER_START_TIMEOUT_MS = 120_000;
const SERVER_START_POLL_INTERVAL_MS = 300;
const DEFAULT_LOCK_WAIT_TIMEOUT_MS = 150_000;
const SERVER_START_TIMEOUT_ENV = 'RIVET_SERVER_START_TIMEOUT_MS';
const LOCK_WAIT_TIMEOUT_ENV = 'RIVET_LOCK_WAIT_TIMEOUT_MS';
const OPEN_RETRY_DELAY_MS = 1_000;
const APP_HEALTH_TIMEOUT_MS = 10_000;
const APP_HEALTH_TIMEOUT_ENV = 'RIVET_APP_HEALTH_TIMEOUT_MS';
const RETRY_OPEN_RECOVERY: CliErrorRecovery = {
  isRecoverable: true,
  nextAction: { action: 'retry', delayMs: OPEN_RETRY_DELAY_MS },
};

const sleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

const waitForServer = async ({
  projectPath,
  timeoutMs,
  isSpawnDead,
  env,
}: {
  projectPath: string;
  timeoutMs: number;
  isSpawnDead?: () => boolean;
  env: NodeJS.ProcessEnv;
}): Promise<AttachedServer | null> => {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const attached = await attachToServer(projectPath, env);
    if (attached) {
      return attached;
    }
    if (isSpawnDead?.()) {
      return null;
    }
    await sleep(SERVER_START_POLL_INTERVAL_MS);
  }
  return null;
};

const serverLogPath = (projectPath: string): string =>
  path.join(serverRuntimeDirectory(projectPath), 'server.log');

const tailServerLog = (projectPath: string): string | undefined => {
  try {
    const contents = fs.readFileSync(serverLogPath(projectPath), 'utf8');
    const lines = contents.trimEnd().split('\n');
    return lines.slice(-12).join('\n') || undefined;
  } catch {
    return undefined;
  }
};

type SpawnServerHandle = {
  pid?: number;
  isDead: () => boolean;
};

export type SpawnServerProcess = (args: {
  projectPath: string;
  serveArgs: string[];
  env: NodeJS.ProcessEnv;
}) => SpawnServerHandle;

const spawnDetachedServer: SpawnServerProcess = ({
  projectPath,
  serveArgs,
  env,
}) => {
  const logPath = serverLogPath(projectPath);
  fs.mkdirSync(path.dirname(logPath), { recursive: true });
  const logFd = fs.openSync(logPath, 'a');
  const child = spawn(
    process.execPath,
    [process.argv[1], '__serve', ...serveArgs],
    {
      cwd: projectPath,
      env,
      detached: true,
      stdio: ['ignore', logFd, logFd],
    },
  );
  let isDead = false;
  child.once('exit', () => {
    isDead = true;
  });
  child.unref();
  fs.closeSync(logFd);
  return { pid: child.pid, isDead: () => isDead };
};

const timeoutFromEnv = (
  env: NodeJS.ProcessEnv,
  name: string,
  fallbackMs: number,
): number => {
  const value = env[name];
  if (!value) {
    return fallbackMs;
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallbackMs;
};

const passthroughServeArgs = (context: CommandContext): string[] => {
  const { flags, projectPath } = context;
  const args: string[] = ['--project', projectPath];
  for (const name of [
    'rivet-port',
    'user-port',
    'framework',
    'entry',
    'style-framework',
    'tailwind-config',
    'agent',
  ] as const) {
    const value = stringFlag(flags, name);
    if (value !== undefined) {
      args.push(`--${name}`, value);
    }
  }
  for (const name of ['no-git', 'no-telemetry', 'debug'] as const) {
    if (flags.values[name] === true) {
      args.push(`--${name}`);
    }
  }
  return args;
};

const USER_PORT_FLAG = '--user-port';

const withoutUserPort = (args: string[]): string[] =>
  args.filter(
    (arg, index) =>
      arg !== USER_PORT_FLAG && args[index - 1] !== USER_PORT_FLAG,
  );

const previewRecoveryServeArgs = (
  context: CommandContext,
  retiredArgs: string[] | undefined,
): string[] => {
  const userPort = stringFlag(context.flags, 'user-port');
  return [
    ...withoutUserPort(retiredArgs ?? passthroughServeArgs(context)),
    ...(userPort === undefined ? [] : [USER_PORT_FLAG, userPort]),
  ];
};

const serveEnvFor = (
  handoff: CallerHandoff | null,
  baseEnv: NodeJS.ProcessEnv,
): NodeJS.ProcessEnv => ({
  ...subprocessEnvironment('rivetRuntime', baseEnv),
  ...callerRunnerPathsEnvEntry(baseEnv),
  ...(handoff
    ? {
        [HANDOFF_ENV_VARS.agent]: handoff.agent,
        ...(handoff.model ? { [HANDOFF_ENV_VARS.model]: handoff.model } : {}),
        ...(handoff.session
          ? { [HANDOFF_ENV_VARS.session]: handoff.session }
          : {}),
      }
    : {}),
});

type SessionStatusPayload = {
  session?: {
    sessionId?: string | null;
    resolvedRunner?: unknown;
    initiator?: unknown;
  };
};

const openedData = async ({
  attached,
  wasAlreadyRunning,
  callerAgent,
}: {
  attached: AttachedServer;
  wasAlreadyRunning: boolean;
  callerAgent?: string;
}): Promise<Record<string, unknown>> => {
  let session: SessionStatusPayload['session'];
  try {
    const status = await requestServer<SessionStatusPayload>(
      attached,
      '/api/cli/status',
    );
    if (status.status === 200) {
      session = status.body.session;
    }
  } catch {}
  return {
    attached: true,
    alreadyRunning: wasAlreadyRunning,
    rivetPort: attached.handshake.rivetPort,
    editorUrl: withLaunchRuntime(editorUrlFor(attached), callerAgent),
    sessionId: session?.sessionId ?? attached.handshake.sessionId,
    applyMode: attached.handshake.applyMode,
    resolvedRunner: session?.resolvedRunner ?? null,
    initiator: session?.initiator ?? null,
    ...versionEnvelopeFields(attached.handshake),
  };
};

const DEFAULT_UPGRADE_SHUTDOWN_TIMEOUT_MS = 10_000;
const UPGRADE_SHUTDOWN_TIMEOUT_ENV = 'RIVET_UPGRADE_SHUTDOWN_TIMEOUT_MS';

export type ProjectRuntimeDependencies = {
  spawnServer?: SpawnServerProcess;
  isAuthenticated?: () => boolean;
  env?: NodeJS.ProcessEnv;
};

const finishProjectOpen = (
  data: Record<string, unknown>,
  io: CliIO,
): CliCommandResult => {
  const runner = data.resolvedRunner as {
    mode?: string;
    reason?: string;
  } | null;
  if (runner?.mode === 'unavailable') {
    io.writeProgress(
      `⚠ No runner available — variant runs will fall back to the host agent.${
        runner.reason ? ` ${runner.reason}` : ''
      }`,
    );
  }
  return okResult(COMMAND, data);
};

export const validateProjectOpen = async ({
  context,
  io,
  isAuthenticated: checkAuthentication,
  signIn,
}: {
  context: CommandContext;
  io: CliIO;
  isAuthenticated?: () => boolean;
  signIn?: () => Promise<CliCommandResult | null>;
}): Promise<CliCommandResult | null> => {
  const agentSelectionError = explicitRunnerSelectionError(
    stringFlag(context.flags, 'agent'),
  );
  if (agentSelectionError) {
    return errorResult(COMMAND, 'USAGE_ERROR', agentSelectionError);
  }

  let isAuthenticated = checkAuthentication;
  if (!isAuthenticated) {
    const { getConfigManager } = await import('../../services/ConfigManager');
    isAuthenticated = () => getConfigManager().isAuthenticated();
  }
  if (isAuthenticated()) return null;
  if (signIn) return signIn();
  io.writeProgress(AUTH_REQUIRED_MESSAGE);
  return errorResult(COMMAND, 'AUTH_REQUIRED', AUTH_REQUIRED_MESSAGE);
};

const verifyRuntimeReadiness = async (
  attached: AttachedServer,
  appHealthTimeoutMs: number,
): Promise<CliCommandResult | null> => {
  const health = await requestServer<{
    rivetVersion?: string;
    pid?: number;
    originalPreviewPath?: string | null;
  }>(attached, '/api/health');
  if (
    health.status !== 200 ||
    health.body.rivetVersion !== attached.handshake.rivetVersion ||
    health.body.pid !== attached.handshake.pid
  ) {
    return errorResult(
      COMMAND,
      'SERVER_UNAVAILABLE',
      'The replacement server could not verify its version and identity.',
      { serverUnavailableReason: 'replacement_health_failed' },
    );
  }
  if (health.body.originalPreviewPath) {
    const deadline = Date.now() + appHealthTimeoutMs;
    while (Date.now() < deadline) {
      const preview = await fetch(
        new URL(health.body.originalPreviewPath, attached.baseUrl),
        { signal: AbortSignal.timeout(Math.max(1, deadline - Date.now())) },
      ).catch(() => null);
      await preview?.body?.cancel().catch(() => undefined);
      if (preview?.ok) return null;
      const remainingMs = deadline - Date.now();
      if (remainingMs > 0)
        await sleep(Math.min(SERVER_START_POLL_INTERVAL_MS, remainingMs));
    }
    return errorResult(
      COMMAND,
      'SERVER_UNAVAILABLE',
      'Rivet started but the application preview is unavailable. Check the app dev server and retry `rivet open`.',
      { serverUnavailableReason: 'app_health_failed' },
      RETRY_OPEN_RECOVERY,
    );
  }
  return null;
};

export const ensureProjectRuntime = async (
  context: CommandContext,
  io: CliIO,
  dependencies: ProjectRuntimeDependencies = {},
): Promise<CliCommandResult> => {
  const { projectPath, handoff } = context;
  const env = dependencies.env ?? process.env;
  const serverStartTimeoutMs = timeoutFromEnv(
    env,
    SERVER_START_TIMEOUT_ENV,
    DEFAULT_SERVER_START_TIMEOUT_MS,
  );
  const lockWaitTimeoutMs = timeoutFromEnv(
    env,
    LOCK_WAIT_TIMEOUT_ENV,
    DEFAULT_LOCK_WAIT_TIMEOUT_MS,
  );
  const appHealthTimeoutMs = timeoutFromEnv(
    env,
    APP_HEALTH_TIMEOUT_ENV,
    Math.min(serverStartTimeoutMs, APP_HEALTH_TIMEOUT_MS),
  );

  const validation = await validateProjectOpen({
    context,
    io,
    isAuthenticated: dependencies.isAuthenticated,
  });
  if (validation) return validation;

  const lockDeadline = Date.now() + lockWaitTimeoutMs;
  let lock = await acquireStartLock(projectPath);
  while (!lock && Date.now() < lockDeadline) {
    invalidateAttachCache();
    const ready = await attachToServer(projectPath, env);
    if (ready) await releaseReadyStartLock(projectPath, ready.handshake.pid);
    lock = await acquireStartLock(projectPath);
    if (!lock) await sleep(SERVER_START_POLL_INTERVAL_MS);
  }
  if (!lock) {
    return errorResult(
      COMMAND,
      'SERVER_UNAVAILABLE',
      'Timed out waiting for the concurrent Rivet runtime handoff.',
      { serverUnavailableReason: 'server_start_timeout' },
      RETRY_OPEN_RECOVERY,
    );
  }
  const spawnServer = dependencies.spawnServer ?? spawnDetachedServer;
  let shouldReleaseStartLock = true;
  try {
    invalidateAttachCache();
    const existing = await attachToServer(projectPath, env);
    const registered = readHandshake(projectPath);
    if (!existing && registered && isPidAlive(registered.pid)) {
      return errorResult(
        COMMAND,
        'SERVER_UNAVAILABLE',
        'The registered project server is alive but its health cannot be verified. Leave it running and inspect its log before retrying.',
        { serverUnavailableReason: 'health_check_failed' },
      );
    }
    let restartArgs: string[] | undefined;
    let interruptedWork: RuntimeInterruption | undefined;
    if (existing) {
      const replacement = await prepareRuntimeUpgrade({
        attached: existing,
        io,
        shutdownTimeoutMs: timeoutFromEnv(
          env,
          UPGRADE_SHUTDOWN_TIMEOUT_ENV,
          DEFAULT_UPGRADE_SHUTDOWN_TIMEOUT_MS,
        ),
      });
      if (replacement.outcome === 'failed') {
        return errorResult(
          COMMAND,
          'SERVER_UNAVAILABLE',
          replacement.message,
          {
            serverUnavailableReason: 'server_upgrade_required',
            upgradeReason: replacement.reason,
          },
          RETRY_OPEN_RECOVERY,
        );
      }
      if (replacement.outcome === 'attach') {
        const readinessError = await verifyRuntimeReadiness(
          existing,
          appHealthTimeoutMs,
        );
        if (!readinessError) {
          return finishProjectOpen(
            await openedData({
              attached: existing,
              wasAlreadyRunning: true,
              callerAgent: context.handoff?.agent,
            }),
            io,
          );
        }
        if (
          serverUnavailableReasonForEnvelope(readinessError.envelope) !==
          'app_health_failed'
        )
          return readinessError;
        const retirement = await retireUnavailablePreview({
          attached: existing,
          clientVersion: serverVersionInfo(existing.handshake).cliVersion,
          shutdownTimeoutMs: timeoutFromEnv(
            env,
            UPGRADE_SHUTDOWN_TIMEOUT_ENV,
            DEFAULT_UPGRADE_SHUTDOWN_TIMEOUT_MS,
          ),
        });
        if (retirement.outcome === 'kept') return readinessError;
        restartArgs = previewRecoveryServeArgs(context, retirement.restartArgs);
        io.writeProgress(
          'The project server is restarting because the app preview is unavailable…',
        );
      } else {
        interruptedWork = replacement.interruptedWork;
        restartArgs = replacement.restartArgs;
      }
    }
    io.writeProgress(`Starting Rivet server for ${projectPath}…`);
    const handle = spawnServer({
      projectPath,
      serveArgs: restartArgs ?? passthroughServeArgs(context),
      env: serveEnvFor(handoff, env),
    });
    const attached = await waitForServer({
      projectPath,
      timeoutMs: serverStartTimeoutMs,
      isSpawnDead: handle.isDead,
      env,
    });
    if (!attached) {
      const logTail = tailServerLog(projectPath);
      const isSpawnDead = handle.isDead();
      if (!isSpawnDead && handle.pid) {
        await lock.holdForProcess(handle.pid, 'starting');
        shouldReleaseStartLock = false;
      }
      return errorResult(
        COMMAND,
        'SERVER_UNAVAILABLE',
        'The Rivet server did not come up. See .rivet/cli/server.log for details.',
        {
          serverUnavailableReason: isSpawnDead
            ? 'server_process_exited'
            : 'server_start_timeout',
          ...(logTail ? { serverLog: logTail } : {}),
        },
        isSpawnDead ? { isRecoverable: false } : RETRY_OPEN_RECOVERY,
      );
    }
    if (serverVersionInfo(attached.handshake).staleServer) {
      return errorResult(
        COMMAND,
        'SERVER_UNAVAILABLE',
        'The replacement server is still older than this client. Retry with the installed Rivet CLI.',
        {
          serverUnavailableReason: 'replacement_version_mismatch',
          ...versionEnvelopeFields(attached.handshake),
        },
      );
    }
    const readinessError = await verifyRuntimeReadiness(
      attached,
      appHealthTimeoutMs,
    );
    if (readinessError) return readinessError;
    const data = await openedData({
      attached,
      wasAlreadyRunning: false,
      callerAgent: context.handoff?.agent,
    });
    return finishProjectOpen(
      { ...data, ...(interruptedWork ? { interruptedWork } : {}) },
      io,
    );
  } finally {
    if (shouldReleaseStartLock) {
      await lock.release();
    }
  }
};
